doc=$(help -d dns)
case "$doc" in
  *"DNS over UDP via hand-rolled RFC 1035."*) printf 'dns description documented\n' ;;
  *) exit 1 ;;
esac

doc=$(help dns)
case "$doc" in
  *"validate an RFC 1035 master file"*"Authoritative DNS daemon"*"DNSSEC v2:"*) printf 'documented command families present\n' ;;
  *) exit 1 ;;
esac
